function pieceVaultable(b) {
  if (!b || b.hp <= 0 || !b.mesh) return false;
  if (b.type === 'sandbag' || b.type === 'wire' || b.type === 'barricade') return true;
  return b.type === 'wall' && b.opening === 'window' && !b.barred;
}
function tryVault() {
  if (vault || marineDown()) return false;
  if (!grounded && coyoteT <= 0) return false;
  const px = player.position.x, pz = player.position.z, py = player.position.y;
  let best = null, bestD = 1.65;
  for (const b of builds) {
    if (!pieceVaultable(b)) continue;
    if (Math.abs(b.mesh.position.y - py) > 1.5) continue;
    const box = thinBoxFor(b);
    const cx = box ? box.cx : b.x, cz = box ? box.cz : b.z;
    const d = Math.hypot(px - cx, pz - cz);
